const country = aliases[String(raw.countryCode || raw.country || '').trim().toLowerCase()] || String(raw.countryCode || raw.country || '').trim().toLowerCase();
const table = String(raw.table || '').trim().toLowerCase();
const maxFiles = Math.max(1, Math.min(20, Number(raw.maxFiles || 10) || 10));
const countries = { cn: ['中国', '10.20.47.14', 36000, '/data/git/starrocks/workflow/cn'], ph: ['菲律宾', '10.20.10.12', '', '/data/git/starrocks/workflow/ph'], ine: ['印尼', '192.168.21.236', 36000, '/data/git/starrocks/workflow/ine'], mx: ['墨西哥', '172.20.220.165', 36000, '/data/git/starrocks/workflow/mx'], th: ['泰国', '192.168.20.236', 36000, '/data/git/starrocks/workflow/th'], pk: ['巴基斯坦', '10.20.84.176', '', '/data/git/starrocks/workflow/pk'] };
const target = countries[country];
const validTable = /^(?:[a-z][a-z0-9_]{0,127}\.)?[a-z][a-z0-9_]{2,127}$/.test(table);
const quote = (value) => "'" + String(value).replace(/'/g, "'"'"'") + "'";
if (operation !== 'trace_table' || !target || !validTable) return [{ json: { valid: false, error: operation !== 'trace_table' ? '暂只支持 operation=trace_table。' : !target ? '不支持的国家，需为 cn/ine/ph/th/pk/mx。' : '表名格式不合法。' } }];
const py = "import json, os, re, sys
root, table, max_files = sys.argv[1], sys.argv[2], int(sys.argv[3])
needle = table.rsplit('.', 1)[-1].lower()
source_pat = re.compile(r'(?i)\b(?:from|join)\s+([`a-z0-9_\.]+)')
output_pat = re.compile(r'(?i)\b(?:insert\s+(?:overwrite|into)\s+(?:table\s+)?|create\s+(?:table\s+)?)([`a-z0-9_\.]+)')
table_prefixes = ('ods_', 'dwd_', 'dwb_', 'dws_', 'ads_', 'dm_', 'dim_')
def normalize(value):
 value = value.strip().lower().replace(chr(96), '').rstrip(';,')
 return value
def is_table(value):
 return bool(re.fullmatch(r'[a-z][a-z0-9_]*(?:\.[a-z][a-z0-9_]*)?', value)) and ('.' in value or value.startswith(table_prefixes))
def same_target(value):
 value = normalize(value)
 return value == table or value.rsplit('.', 1)[-1] == needle
def strip_comments(value):
 value = re.sub(r'/\*.*?\*/', '', value, flags=re.S)
 return '\n'.join(line.split('--', 1)[0] for line in value.splitlines())
def matching_lines(value):
 pattern = re.compile(r'(?i)(?<![a-z0-9_])' + re.escape(needle) + r'(?![a-z0-9_])')
 return [{'line': index, 'text': line.strip()[:500]} for index, line in enumerate(value.splitlines(), 1) if pattern.search(line)][:8]
hits, upstream, downstream, related = [], set(), set(), set()
producer_files, sql_consumer_files, dependency_files = [], [], []
for base, dirs, files in os.walk(root):
 dirs[:] = [item for item in dirs if item not in ('.git', 'node_modules', 'target', 'dist')]
 for name in files:
  priority_candidate = os.path.splitext(name)[0].lower() == needle or os.path.basename(base).lower() == needle
  if len(hits) >= max_files and not priority_candidate: continue
  if not name.lower().endswith(('.sql', '.py', '.sh', '.scala', '.java')): continue
  path = os.path.join(base, name)
  try:
   if os.path.getsize(path) > 2097152: continue
   raw = open(path, encoding='utf-8', errors='ignore').read()
  except OSError: continue
  if not re.search(r'(?i)(?<![a-z0-9_])' + re.escape(needle) + r'(?![a-z0-9_])', raw): continue
  sql = strip_comments(raw)
  sources = {normalize(item) for item in source_pat.findall(sql) if is_table(normalize(item))}
  outputs = {normalize(item) for item in output_pat.findall(sql) if is_table(normalize(item))}
  direct_source = any(same_target(item) for item in sources)
  producer = any(same_target(item) for item in outputs)
  declared_dependency = bool(re.search(r'(?im)^\s*(?:--\s*)?dependency\s*:\s*\[[^\]]*' + re.escape(needle) + r'[^\]]*\]', raw))
  role = 'producer_sql' if producer else 'consumer_sql' if direct_source else 'declared_dependency' if declared_dependency else 'text_reference'
  if producer:
   producer_files.append(os.path.relpath(path, root))
   upstream.update(item for item in sources if not same_target(item))
  relative_path = os.path.relpath(path, root)
  if direct_source:
   sql_consumer_files.append(relative_path)
   downstream.update(item for item in outputs if not same_target(item))
  elif declared_dependency:
   dependency_files.append(relative_path)
   path_parts = relative_path.split(os.sep)
   layer = path_parts[0].lower() if path_parts else ''
   file_table = os.path.splitext(os.path.basename(path))[0].lower()
   primary_output = layer + '.' + file_table
   if primary_output in outputs: downstream.add(primary_output)
   elif len(outputs) == 1: downstream.update(outputs)

  related.update((sources | outputs) - {table, needle})
  entry = {'path': relative_path, 'role': role, 'matches': matching_lines(raw), 'outputTables': sorted(outputs)[:10], 'sourceTables': sorted(sources)[:20]}
  if len(hits) < max_files: hits.append(entry)
  elif producer: hits[-1] = entry
quality = 'producer_sql' if producer_files else 'consumer_sql' if sql_consumer_files else 'declared_dependency_only' if dependency_files else 'text_reference_only'
print(json.dumps({'success': True, 'table': table, 'repository': root, 'matchedFiles': hits, 'upstreamTables': sorted(upstream)[:30], 'downstreamTables': sorted(downstream)[:30], 'relatedTables': sorted(related - upstream - downstream)[:30], 'dsRefs': [], 'evidence': {'quality': quality, 'producerFiles': producer_files[:10], 'consumerFiles': sql_consumer_files[:10], 'declaredDependencyFiles': dependency_files[:10], 'warning': '静态代码血缘仅作为取证线索；只有 producer_sql 的 upstreamTables 可用于递归追溯。'}, 'truncated': len(hits) >= max_files}, ensure_ascii=False))";
const encoded = Buffer.from(py, 'utf8').toString('base64');
const remote = `set -euo pipefail; repo=${quote(target[3])}; [ -d "$repo" ] || { echo repository-not-found >&2; exit 2; }; printf %s ${quote(encoded)} | base64 -d | python3 - "$repo" ${quote(table)} ${quote(maxFiles)}`;
const command = ['ssh', target[2] ? '-p ' + target[2] : '', '-o BatchMode=yes', '-o ConnectTimeout=20', quote('root@' + target[1]), quote('bash -lc ' + quote(remote))].filter(Boolean).join(' ');
return [{ json: { valid: true, operation, country, countryName: target[0], table, repository: target[3], command } }];

const result = $json;
const isTable = (value) => { const text = String(value || '').toLowerCase(); return text.includes('.') || /^(ods|dwd|dwb|dws|ads|dm|dim)_/.test(text); };
const uniqueTables = (values) => Array.from(new Set((values || []).filter(isTable))).slice(0, 30);
